// ---- helpers (shared by the workflows in this pack) ----
const cfg = $('Config').first().json;
const zone = cfg.timezone || 'UTC';
const now = DateTime.now().setZone(zone);
const today = now.startOf('day');

// Read the first non-empty value among several possible column names.
const val = (row, ...keys) => {
  for (const k of keys) {
    const v = row[k];
    if (v !== undefined && v !== null && String(v).trim() !== '') return String(v).trim();
  }
  return '';
};

// Accepts 2026-11-20, 2026-11-20T14:30, 11/20/2026, 20.11.2026, Nov 20, 2026 or a Sheets serial number.
function parseDate(v) {
  if (v === undefined || v === null || v === '') return null;
  if (typeof v === 'number') {
    return DateTime.fromMillis(Math.round((v - 25569) * 86400000), { zone: 'utc' })
      .setZone(zone, { keepLocalTime: true });
  }
  const s = String(v).trim();
  let d = DateTime.fromISO(s, { zone });
  if (d.isValid) return d;
  d = DateTime.fromSQL(s, { zone });
  if (d.isValid) return d;
  for (const f of ['M/d/yyyy', 'M/d/yyyy H:mm', 'M/d/yyyy h:mm a', 'M/d/yy', 'd.M.yyyy', 'yyyy/M/d', 'd MMM yyyy', 'MMM d, yyyy', 'MMMM d, yyyy']) {
    d = DateTime.fromFormat(s, f, { zone });
    if (d.isValid) return d;
  }
  const js = new Date(s);
  return isNaN(js) ? null : DateTime.fromJSDate(js).setZone(zone);
}

// Whole days between a date and today (positive = in the past).
const daysAgo = (d) => Math.round(today.diff(d.startOf('day'), 'days').days);

const firstName = (name) => (String(name || '').trim().split(/\s+/)[0] || 'there');

const toNumber = (v) => {
  if (typeof v === 'number') return v;
  const n = parseFloat(String(v ?? '').replace(/[^0-9.\-]/g, ''));
  return isNaN(n) ? 0 : n;
};

function money(amount, currency) {
  const cur = (currency || cfg.currency || 'USD').toUpperCase();
  try {
    return new Intl.NumberFormat(cfg.locale || 'en-US', { style: 'currency', currency: cur }).format(toNumber(amount));
  } catch (e) {
    return cur + ' ' + toNumber(amount).toFixed(2);
  }
}

const esc = (s) => String(s ?? '').replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));

const button = (url, label) => url
  ? `<p style="margin:24px 0"><a href="${esc(url)}" style="background:${cfg.brandColor || '#2563eb'};color:#ffffff;padding:12px 22px;border-radius:6px;text-decoration:none;font-weight:bold;display:inline-block">${esc(label)}</a></p>`
  : '';

// Wraps body HTML in a clean, mobile-friendly email layout.
const layout = (inner) => `<div style="font-family:Arial,Helvetica,sans-serif;font-size:15px;line-height:1.6;color:#1f2937;max-width:560px;margin:0 auto;padding:24px">${inner}<p style="margin-top:32px;color:#6b7280;font-size:13px">${esc(cfg.businessName || '')}</p></div>`;
// ---- end helpers ----

// Follow-up schedule (days after the lead came in). Edit the wording freely.
const STEPS = [
  { afterDays: 2, subject: 'Following up on your inquiry',
    body: 'I wanted to check you saw our reply to your inquiry. Happy to answer any questions or set up a quick call — whatever is easiest.' },
  { afterDays: 5, subject: 'Any questions I can answer?',
    body: 'Just bumping this up in case it got buried. If it helps, you can grab a time that suits you below and we can chat it through in 10 minutes.' },
  { afterDays: 10, subject: 'Should I close your file?',
    body: "I haven't heard back, so I'm guessing the timing isn't right — totally fine! I'll close your inquiry for now. If anything changes, just reply to this email and we'll pick it straight back up." },
];
const out = [];
$input.all().forEach((item, i) => {
  const r = item.json;
  const status = val(r, 'Status').toLowerCase();
  if (status && status !== 'new') return;                 // Contacted / Won / Lost etc. are left alone
  const email = val(r, 'Email');
  const created = parseDate(r['Date']);
  if (!email || !created) return;
  const sent = Math.floor(toNumber(r['Follow-ups Sent']));
  const step = STEPS[sent];
  if (!step || daysAgo(created) < step.afterDays) return;
  const last = parseDate(r['Last Follow-up']);
  if (last && daysAgo(last) < 1) return;                  // never two in one day

  const name = firstName(val(r, 'Name'));
  out.push({
    json: {
      email, name, phone: val(r, 'Phone'), step: sent + 1, daysOld: daysAgo(created),
      subject: step.subject,
      html: layout(`<p>Hi ${esc(name)},</p><p>${step.body}</p>` + (sent === 1 ? button(cfg.bookingLink, 'Book a quick call') : '') + `<p>Best,<br>${esc(cfg.senderName || '')}</p>`),
      followUpsSent: sent + 1,
      today: today.toISODate(),
    },
    pairedItem: { item: i },
  });
});
return out;

